pm.test('a reset completion with no code is rejected and names the code field', function () {
  pm.expect(pm.response.code).to.equal(400);
  const body = pm.response.json();
  pm.expect(body).to.have.property('code');
});

pm.test('a reset completion with no new password is rejected and names the password field', function () {
  pm.expect(pm.response.code).to.equal(400);
  const body = pm.response.json();
  pm.expect(body).to.have.property('password');
});

pm.test('a completion with an unrecognised code is refused (one of the four \'bad code\' causes this requirement covers - see postman/assertions/out_of_scope.json for the other three)', function () {
  pm.expect(pm.response.code).to.equal(400);
});

pm.test('a refused reset completion returns HTTP 400', function () {
  pm.expect(pm.response.code).to.equal(400);
});

pm.test('a reset completion response never contains the submitted password', function () {
  pm.expect(pm.response.text()).to.not.include('Passw0rd1');
});
